#!/usr/bin/env python3
"""Retained point-edge dimensions through real Alloy; native Qt gesture separate."""
import argparse,json,math
from pathlib import Path
from app_harness import application
p=argparse.ArgumentParser();p.add_argument('--app',required=True);p.add_argument('--output',required=True);a=p.parse_args();out=Path(a.output).resolve()
with application(a.app,out) as (call,log):
    def draft():return call('app.state')['activeSession']['draftSketch']
    def inspect():return call('document.inspect')
    call('sketch.begin',{'plane':'XY'});call('sketch.rectangle',{'x1':0,'y1':0,'x2':40,'y2':25,'units':'mm'});base=draft();edges=base['parameters']['entities'];call('sketch.constraint',{'type':'fixed','pointIds':[edges[0]['startPointId']]});call('sketch.dimension',{'kind':'horizontal','entityId':edges[0]['id'],'value':40,'units':'mm'});width=draft()['parameters']['dimensions'][-1]['id'];call('sketch.dimension',{'kind':'vertical','entityId':edges[1]['id'],'value':25,'units':'mm'});call('sketch.finish');baseid=base['id'];profile=inspect()['evaluation']['sketches'][0]['profiles'][0]['profileId'];call('solid.extrude',{'sketchId':baseid,'profileId':profile,'distance':5,'units':'mm'})
    stock=inspect();body=stock['evaluation']['bodies'][0];face=next(f for f in body['supportFaces'] if f['role']=='extrude.endCap');support={k:face[k] for k in ('bodyId','producerFeatureId','faceId')};call('sketch.begin',{'support':support});call('sketch.addCircle',{'centerX':30,'centerY':12,'diameter':6,'units':'mm'});circle=draft()['parameters']['entities'][0];point=circle['centerPointId'];holeid=draft()['id'];call('view.orientation',{'name':'top'});call('view.home')
    projections=call('app.state')['activeSession']['projectionContext']['lines'];right=next(l for l in projections if abs(l['u1Mm']-40)<1e-6 and abs(l['u2Mm']-40)<1e-6);bottom=next(l for l in projections if abs(l['v1Mm'])<1e-6 and abs(l['v2Mm'])<1e-6)
    def pixels(u,v):return call('view.projectSketchPoint',{'sketchId':holeid,'uMm':u,'vMm':v})
    call('sketch.tool',{'tool':'dimension'})
    for edge,value,placement in [(right,5,(43,12)),(bottom,10,(35,1))]:
        call('sketch.selectionSet',{'pointIds':[point],'entityIds':[edge['id']]});position=pixels(*placement);preview=call('sketch.dimensionPreview',{'x':position['x'],'y':position['y']});assert preview['kind']=='pointLineDistance' and preview['phase']=='placing';before=draft();call('sketch.dimensionPlace',{'x':position['x'],'y':position['y']});call('sketch.dimensionAccept',{'text':str(value)});assert len(draft()['parameters']['dimensions'])==len(before['parameters'].get('dimensions',[]))+1
    call('sketch.dimension',{'kind':'radius','entityId':circle['id'],'value':3});first=draft()['parameters']['dimensions'][0];assert first['pointIds']==[point] and first['entityId']==right['id'] and abs(first['side'])==1
    # Placement-only edit stays separate from actual sketch geometry.
    geometry_before=draft()['parameters'];call('sketch.annotationMove',{'dimensionId':first['id'],'uMm':44,'vMm':15});geometry_after=draft()['parameters'];assert geometry_before['points']==geometry_after['points'] and geometry_before['entities']==geometry_after['entities']
    call('sketch.tool',{'tool':'select'});call('sketch.dimensionUpdate',{'dimensionId':first['id'],'value':6});assert math.isclose(next(p for p in draft()['parameters']['points'] if p['id']==point)['uMm'],34,abs_tol=1e-6);call('history.undo');assert draft()['parameters']['dimensions'][0]['valueMm']==5
    call('capture.screenshot',{'path':str(out/'point-edge-dimensions.png')});call('sketch.finish');state=inspect();hole=state['evaluation']['sketches'][-1];call('solid.extrude',{'sketchId':holeid,'profileId':hole['profiles'][0]['profileId'],'operation':'cut','targetBodyIds':[body['bodyId']],'distance':-5,'units':'mm'});before=inspect();assert math.isclose(before['evaluation']['bodies'][0]['volumeMm3'],5000-45*math.pi,abs_tol=1e-5)
    call('sketch.edit',{'sketchId':baseid});call('sketch.dimensionUpdate',{'dimensionId':width,'value':50});call('sketch.finish');after=inspect();assert math.isclose(after['evaluation']['bodies'][0]['volumeMm3'],6250-45*math.pi,abs_tol=1e-5);center=next(p for p in after['evaluation']['sketches'][-1]['worldPoints'] if p['id']==point)['positionMm'];assert math.isclose(center[0],45,abs_tol=1e-6) and math.isclose(center[1],10,abs_tol=1e-6)
    retained=next(f for f in after['authored']['features'] if f['id']==holeid)['parameters'];old=next(f for f in before['authored']['features'] if f['id']==holeid)['parameters'];assert retained['dimensions']==old['dimensions'] and retained['projections']==old['projections'];call('history.undo');assert inspect()['authored']==before['authored'];call('history.redo');assert inspect()['authored']==after['authored']
    path=out/'retained-hole.alloy';call('document.save',{'path':str(path)});call('document.open',{'path':str(path)});assert inspect()['authored']==after['authored'];call('capture.screenshot',{'path':str(out/'resized-retained-hole.png')});(out/'report.json').write_text(json.dumps({'passed':True,'scope':'shared API and geometry/history/storage; Qt gestures separate','before':before,'after':after},indent=2));(out/'transcript.json').write_text(json.dumps(log,indent=2))
